import Foundation

/// Entscheidet, ob und was aus einer Änderung der Zwischenablage in den Verlauf kommt (0.11.0, G37).
/// Reine Logik über eine Momentaufnahme – testbar ohne echte Zwischenablage.
enum ClipboardCapture {

    /// Fest, nicht abschaltbar: so markieren Passwort-Manager und Systemdienste ihre Kopien (nspasteboard.org).
    static let neverTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
    ]

    enum UTI {
        static let plain = "public.utf8-plain-text"
        static let rtf = "public.rtf"
        static let html = "public.html"
        static let url = "public.url"
        static let fileURL = "public.file-url"
        static let png = "public.png"
        static let tiff = "public.tiff"
        static let jpeg = "public.jpeg"
        static let heic = "public.heic"
    }

    /// Feste Typenliste (G37). Nicht dabei: Webarchiv, SVG/PDF, Browser-interne Typen.
    static let textTypes = [UTI.plain, UTI.rtf, UTI.html, UTI.url, UTI.fileURL]
    /// Bilder: nur EIN Format übernehmen, in dieser Reihenfolge (TIFF ist oft riesig, daher hinten).
    static let imageTypes = [UTI.png, UTI.jpeg, UTI.heic, UTI.tiff]

    static let maxTextBytes = 1_000_000
    static let maxTotalBytes = 20_000_000

    struct Snapshot {
        let types: [String]
        let read: (String) -> Data?
        let sourceBundleID: String?
    }

    enum SkipReason: String, Equatable, Error {
        case confidential = "vertraulich"
        case excluded = "ausgeschlossen"
        case empty = "leer"
        case tooLarge = "zu groß"
        case unsupported = "nicht unterstützt"
    }

    enum Decision: Equatable {
        case skip(SkipReason)
        case take(ClipPayload, ClipKind)
    }

    static func decide(_ snapshot: Snapshot, isExcluded: (String) -> Bool) -> Decision {
        if snapshot.types.contains(where: neverTypes.contains) { return .skip(.confidential) }
        if let source = snapshot.sourceBundleID, isExcluded(source) { return .skip(.excluded) }
        let present = Set(snapshot.types)
        let formats: [ClipPayload.Format]
        switch collect(snapshot, present: present) {
        case .failure(let reason): return .skip(reason)
        case .success(let found): formats = found
        }
        guard !formats.isEmpty else { return present.isEmpty ? .skip(.empty) : .skip(.unsupported) }
        // Bild ohne Klartext/Link/Datei = Bild, nur das Bildformat behalten. Gemessen 24.10. an Safari „Bild kopieren“:
        // public.tiff + public.html (nur <img src=…> auf die Webadresse) – vorher als leerer Text verworfen.
        let textual: Set<String> = [UTI.plain, UTI.url, UTI.fileURL]
        if let image = formats.first(where: { imageTypes.contains($0.type) }),
           formats.allSatisfy({ !textual.contains($0.type) }) {
            return .take(ClipPayload(formats: [image], plain: ""), .image)
        }
        let plain = plainText(formats)
        let kind = kind(of: Set(formats.map(\.type)), plain: plain)
        if kind != .image && kind != .file && plain.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            return .skip(.empty)
        }
        return .take(ClipPayload(formats: formats, plain: plain), kind)
    }

    /// Erlaubte Formate einsammeln, mit Größengrenzen (Text je 1 MB, alles zusammen 20 MB).
    private static func collect(_ snapshot: Snapshot, present: Set<String>) -> Result<[ClipPayload.Format], SkipReason> {
        var formats: [ClipPayload.Format] = []
        for type in textTypes where present.contains(type) {
            guard let data = snapshot.read(type), !data.isEmpty else { continue }
            if data.count > maxTextBytes { return .failure(.tooLarge) }
            formats.append(.init(type: type, data: data))
        }
        if let imageType = imageTypes.first(where: present.contains), let data = snapshot.read(imageType), !data.isEmpty {
            formats.append(.init(type: imageType, data: data))
        }
        let total = formats.reduce(0) { $0 + $1.data.count }
        return total > maxTotalBytes ? .failure(.tooLarge) : .success(formats)
    }

    private static func kind(of types: Set<String>, plain: String) -> ClipKind {
        if types.contains(UTI.fileURL) { return .file }
        if types.isDisjoint(with: [UTI.plain, UTI.rtf, UTI.html, UTI.url]) { return .image }
        if types.contains(UTI.rtf) || types.contains(UTI.html) { return .richText }
        if types.contains(UTI.url) || isSingleWebURL(plain) { return .link }
        return .text
    }

    /// Reiner Text: Klartext-Format, sonst URL, sonst Dateiname. RTF/HTML werden NIE geparst (G40).
    static func plainText(_ formats: [ClipPayload.Format]) -> String {
        func string(_ type: String) -> String? {
            formats.first { $0.type == type }.flatMap { String(bytes: $0.data, encoding: .utf8) }
        }
        if let plain = string(UTI.plain) { return plain }
        if let url = string(UTI.url) { return url }
        if let file = string(UTI.fileURL), let url = URL(string: file) { return url.lastPathComponent }
        return ""
    }

    static func isSingleWebURL(_ text: String) -> Bool {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.contains(where: \.isWhitespace), let url = URL(string: trimmed),
              let scheme = url.scheme?.lowercased() else { return false }
        return (scheme == "http" || scheme == "https") && url.host != nil
    }
}
